starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 3.0"
    }
  }
}

starter.variables.tf:
variable "docker_host" {
  description = "Docker daemon endpoint."
  type        = string
  default     = "npipe:////./pipe/docker_engine"
}

variable "container_name" {
  description = "Container name."
  type        = string
  default     = "tf-arena-nginx"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]*$", var.container_name))
    error_message = "Use lowercase letters, numbers and hyphens."
  }
}

variable "host_port" {
  description = "Host port."
  type        = number
  default     = 8080

  validation {
    condition     = var.host_port >= 1024 && var.host_port <= 65535
    error_message = "Use a port between 1024 and 65535."
  }
}

variable "image_name" {
  description = "Container image."
  type        = string
  default     = "nginx:alpine"
}

variable "project_name" {
  description = "Project name used for labels."
  type        = string
  default     = "terraform-practice"
}

variable "environment" {
  description = "Deployment environment."
  type        = string
  default     = "dev"
}

starter.main.tf:
provider "docker" {
  host = var.docker_host
}

resource "docker_image" "this" {
  name = var.image_name
}

resource "docker_container" "this" {
  # TODO - Complete the Nginx container.
  # Wire the name, image, restart policy, published port and operational labels.
}

starter.outputs.tf:
output "container_id" {
  description = "Container id."
  value       = docker_container.this.id
}

output "container_name" {
  description = "Container name."
  value       = docker_container.this.name
}

output "url" {
  description = "Local URL for the published port."
  value       = "http://localhost:${var.host_port}"
}
